input.content:
/* ───────────── Session 4 slides ───────────── */

.walk-slide h2 { font-size: 46px; margin: 4px 0 20px; }
.punch-step { margin-top: 26px; }

/* cómo les fue */
.notes3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 34px; margin-top: 60px; }
.notes3 .card { height: 260px; display: flex; flex-direction: column; justify-content: space-between; font-size: 34px; font-weight: 700; }
.notes3 .card .emo { font-size: 60px; align-self: flex-end; }
.notes3 .card:nth-child(1) { background: color-mix(in srgb, var(--a3) 45%, var(--card)); }
.notes3 .card:nth-child(2) { background: color-mix(in srgb, var(--a2) 30%, var(--card)); }
.notes3 .card:nth-child(3) { background: color-mix(in srgb, var(--a1) 32%, var(--card)); }

/* deuda */
.debt { display: grid; grid-template-columns: 1fr 1fr; gap: 34px; margin-top: 20px; width: 960px; }
.debt .card { display: flex; flex-direction: column; gap: 12px; min-height: 290px; font-size: 25px; line-height: 1.3; }
.debt .card .ico { font-size: 46px; line-height: 1; }
.debt .card h3 { margin: 0; }
.debt .card:nth-child(1) { background: color-mix(in srgb, var(--a2) 26%, var(--card)); }
.debt .card:nth-child(2) { background: color-mix(in srgb, var(--a1) 24%, var(--card)); }
.debt-slide .punch-step { margin-top: 40px; width: 960px; }

/* AGENTS.md como índice */
.index-cmp { display: grid; grid-template-columns: 1fr 1fr; gap: 34px; }
.index-cmp .card { display: flex; flex-direction: column; gap: 14px; height: 370px; }
.index-cmp h3 { margin: 0; }
.index-cmp .giant { background: color-mix(in srgb, var(--a1) 18%, var(--card)); }
.index-cmp .lean { background: color-mix(in srgb, var(--a4) 20%, var(--card)); }
.mdlines { display: flex; flex-direction: column; gap: 8px; padding: 12px 16px; border: 2px solid color-mix(in srgb, var(--ink) 40%, transparent); border-radius: 10px; background: var(--card); }
.mdlines .path { margin-bottom: 4px; font-family: var(--font-mono); font-size: 15px; color: var(--muted); }
.mdlines i { height: 6px; border-radius: 3px; background: color-mix(in srgb, var(--ink) 30%, transparent); }
.mdlines i:nth-of-type(3n) { width: 64%; }
.mdlines i:nth-of-type(3n + 1) { width: 86%; }
.mdlines.short { width: 230px; }
.idx { display: flex; gap: 24px; align-items: flex-start; }
.links { display: flex; flex-direction: column; gap: 10px; font-family: var(--font-mono); font-size: 17px; }
.links span { padding: 4px 10px; border: 2px solid var(--a4); border-radius: 8px; white-space: nowrap; }
.ctxrow { margin-top: auto; display: flex; flex-direction: column; gap: 8px; }
.ctx { position: relative; height: 28px; border: var(--border); border-radius: 999px; overflow: hidden; background: var(--term-bg); }
.ctx i { position: absolute; left: 0; top: 0; bottom: 0; width: 0; background: var(--a3); transition: width 1.1s cubic-bezier(.3, .9, .4, 1) .35s; }
.ctx::after { content: ""; position: absolute; left: 50%; top: 0; bottom: 0; border-left: 2px dashed var(--muted); }
.on .ctx i { width: var(--w); }
.giant .ctx i { background: var(--a1); }
.lean .ctx i { background: var(--a4); }

/* qué va en cada lugar */
.places { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; margin-top: 10px; }
.places .card { display: flex; flex-direction: column; gap: 10px; height: 400px; font-size: 22px; line-height: 1.3; padding: 22px 20px; }
.places .card .ico { font-size: 46px; line-height: 1; }
.places .card h3 { margin: 0; font-family: var(--font-mono); font-size: 26px; }
.places .card .who { margin-top: auto; font-size: 18px; color: var(--muted); }
.places .card:nth-child(1) { background: color-mix(in srgb, var(--a3) 30%, var(--card)); }
.places .card:nth-child(2) { background: color-mix(in srgb, var(--a2) 28%, var(--card)); }
.places .card:nth-child(3) { background: color-mix(in srgb, var(--a1) 24%, var(--card)); }
.places .card:nth-child(4) { background: color-mix(in srgb, var(--a4) 24%, var(--card)); }

/* dominio del problema */
.domain { display: grid; grid-template-columns: 430px 1fr; gap: 40px; align-items: start; }
.need { display: flex; flex-direction: column; gap: 16px; padding-top: 10px; }
.sticky { padding: 26px 28px; font-size: 32px; font-weight: 700; line-height: 1.25; color: #111; background: var(--a3); border-radius: 6px; transform: rotate(var(--r, 0deg)); }
.points { display: flex; flex-direction: column; gap: 14px; }
.point { display: grid; grid-template-columns: 46px 1fr; gap: 2px 14px; align-items: center; padding: 12px 20px; font-size: 21px; line-height: 1.3; }
.point .ico { grid-row: span 2; font-size: 34px; text-align: center; }
.point b { font-family: var(--font-display); font-size: 26px; }
.point span:last-child { color: var(--muted); }

/* muchas soluciones */
.many { display: flex; flex-direction: column; align-items: center; }
.small-sticky { font-size: 28px; padding: 16px 26px; }
.fan { width: 100%; height: 70px; overflow: visible; }
.fan path { fill: none; stroke: var(--line); stroke-width: 4; stroke-linecap: round; opacity: 1; transform: none; }
.fan path[data-step] { opacity: 1; transform: none; }
.sols { display: grid; grid-template-columns: repeat(3, 1fr); gap: 30px; width: 100%; }
.sols .card { display: flex; align-items: center; gap: 16px; min-height: 120px; font-size: 25px; font-weight: 700; line-height: 1.25; background: color-mix(in srgb, var(--a2) 26%, var(--card)); }
.sols .card .ico { font-size: 40px; }
.many-slide > .mascot { --size: 100px; right: 70px; top: 40px; bottom: auto; }

/* que te pregunte */
.ask { display: grid; grid-template-columns: 560px 1fr; gap: 34px; align-items: start; }
.tree { width: 560px; height: 360px; overflow: visible; }
.tree .edge { fill: none; stroke: var(--line); stroke-width: 3; opacity: .5; }
.tree rect { fill: var(--card); stroke: var(--line); stroke-width: 3; rx: 12; transition: fill .3s, stroke-dasharray .3s; }
.tree text { font-family: var(--font-body); font-size: 20px; fill: var(--ink); text-anchor: middle; dominant-baseline: middle; }
.tree .root rect { fill: color-mix(in srgb, var(--a3) 50%, var(--card)); }
.tree .br > rect { fill: color-mix(in srgb, var(--a2) 35%, var(--card)); }
.tree .leaf rect { stroke-dasharray: 8 7; fill: transparent; }
.tree .leaf .an { display: none; }
.tree .leaf .qm { font-family: var(--font-display); font-weight: 700; font-size: 26px; fill: var(--a1); }
.tree .settled .leaf rect { stroke-dasharray: none; fill: color-mix(in srgb, var(--good) 35%, var(--card)); }
.tree .settled .leaf .an { display: inline; }
.tree .settled .leaf .qm { display: none; }
.tree .fresh .leaf { animation: chipIn .4s both; transform-box: fill-box; transform-origin: center; }
.ask .term { padding-bottom: 0; }
.ask .chat .viewport { height: 300px; }
.ask .chat .line { font-size: 20px; padding: 4px 22px; }
.ask .chat .line.ans { padding-left: 54px; }

/* dominio de la solución */
.design { display: grid; grid-template-columns: 506px 1fr; gap: 34px; align-items: start; }
.bp { position: relative; width: 506px; height: 316px; border: var(--border); border-radius: 16px; box-shadow: var(--shadow); overflow: hidden; background-color: #1c4f8c; background-image: linear-gradient(#ffffff1c 1px, transparent 1px), linear-gradient(90deg, #ffffff1c 1px, transparent 1px); background-size: 20px 20px; }
.bp svg { position: absolute; left: 0; top: 0; width: 500px; height: 310px; overflow: visible; }
.bp .layer { opacity: 0; transition: opacity .4s; }
.sol-slide[data-step="1"] .bp .l1, .sol-slide[data-step="2"] .bp .l2, .sol-slide[data-step="3"] .bp .l3, .sol-slide[data-step="4"] .bp .l2 { opacity: 1; }
.bp .ln { fill: none; stroke: #eaf2ff; stroke-width: 4; stroke-linecap: round; stroke-linejoin: round; }
.bp .ln.arrow { stroke: var(--a3); stroke-width: 3; }
.bp .draw { stroke-dasharray: 100; stroke-dashoffset: 100; transition: stroke-dashoffset 1.2s ease-out; }
.sol-slide[data-step="1"] .l1 .draw, .sol-slide[data-step="2"] .l2 .draw, .sol-slide[data-step="3"] .l3 .draw, .sol-slide[data-step="4"] .l2 .draw { stroke-dashoffset: 0; }
.bp .l1 .arrow, .bp .l3 .link { transition-delay: .8s; }
.bp circle { fill: #eaf2ff; opacity: .6; }
.bp .btn { fill: var(--a2); stroke: #eaf2ff; stroke-width: 3; }
.bp text { font-family: var(--font-mono); font-size: 17px; fill: #eaf2ff; text-anchor: middle; }
.bp text.row { text-anchor: start; }
.bp text.hotrow { fill: var(--a3); font-weight: 700; }
.bp text.note { font-size: 14px; fill: #b8cdf0; }
.bp text.title { font-family: var(--font-display); font-weight: 700; font-size: 24px; text-anchor: start; }
.bp text.btntxt { font-family: var(--font-body); font-weight: 700; font-size: 17px; }
.sol-slide[data-step="4"] .bp { box-shadow: 0 0 0 6px var(--a3), var(--shadow); transition: box-shadow .4s; }

/* bloques en fila */
.blk { padding: 14px 18px; border: var(--border); border-radius: 14px; background: var(--card); box-shadow: 5px 5px 0 #05051a; white-space: nowrap; font-size: 24px; font-weight: 700; }
.blk small { display: block; margin-top: 4px; font-size: 15px; font-weight: 400; color: var(--muted); white-space: normal; max-width: 240px; }
.blk.rev { background: color-mix(in srgb, var(--a1) 40%, var(--card)); }
.blk.calm { background: color-mix(in srgb, var(--a4) 35%, var(--card)); }
.blk.des { background: color-mix(in srgb, var(--a2) 35%, var(--card)); }
.arrow { padding-top: 14px; font-size: 30px; font-weight: 700; color: var(--muted); }
