// One slide per concept along the day's route: the rider hops in from the previous stop, and a slide's chat plays one group per click
const walkStep = (pos, extra = () => {}) => (step, el, ctx) => {
  const track = $(".track", el);
  const rider = $(".rider", track);

  if (ctx.entered) {
    const token = visit;
    const from = ctx.forward ? Math.max(pos - 1, 0) : pos;

    rider.style.transition = "none";
    setTrack(track, from);
    void rider.offsetWidth;
    rider.style.transition = "";
    setMood(rider, "happy");

    if (ctx.forward && from !== pos) {
      setTimeout(() => {
        if (token === visit) {
          replay(rider, "jump");
          setTrack(track, pos);
        }
      }, 500);
    }
  }

  if ($(".chat", el) != null) {
    playChat(step, el, ctx.forward);
  }

  extra(step, el, ctx);
};

const hooks = {
  portada: (step, el, { entered }) => {
    const m = $(".mascot", el);

    if (!entered) {
      return;
    }

    // Tied to the visit, not the render: the re-render after the web fonts load must not cut the typing
    const token = visit;
    m.classList.remove("enter");
    m.style.opacity = 0;

    typeInto($(".typed", el), "Context Engineering", 70, token, () => visit).then(() => {
      if (token !== visit) {
        return;
      }

      m.style.opacity = 1;
      m.classList.add("enter");
    });
  },

  hoy: (step, el, { entered }) => {
    const track = $(".track", el);

    if (entered) {
      redraw(track);
    }

    setTrack(track, 0);
  },

  deuda: (step, el) => setMood($(".mascot", el), step >= 3 ? "joy" : step === 2 ? "sweat" : "skeptic"),

  indice: walkStep(0),

  lugares: walkStep(0),

  problema: walkStep(1),

  muchas: walkStep(1, (step, el) => setMood($(".mascot", el), step >= 4 ? "skeptic" : step >= 1 ? "wow" : "happy")),

  preguntas: walkStep(1, (step, el, { forward }) => {
    $$(".tree .br", el).forEach((b, i) => {
      b.classList.toggle("settled", i < step);
      b.classList.toggle("fresh", forward && i === step - 1);
    });
  }),

  solucion: walkStep(2),

  documentar: walkStep(3, (step, el) => drawBack($(".alive", el))),

  plantillas: walkStep(3),

  criterio: walkStep(3),

  subagentes: walkStep(4, (step, el, { forward }) => {
    const ctx = $(".main-ctx", el);
    const pct = $(".pct-main", el);
    const m = $(".main .mascot", el);
    const used = 14 + 2 * Math.min(step, 3);
    const token = run;

    const settle = () => {
      ctx.style.setProperty("--w", `${used}%`);
      pct.textContent = `contexto: ${used}%`;
    };

    if (!forward || step === 0 || step > 3) {
      settle();
      setMood(m, step > 3 ? "joy" : "happy");
      return;
    }

    setMood(m, "wow");

    // The main context grows only when the summary comes back, not while the subagent works
    setTimeout(() => {
      if (token === run) {
        settle();
        setMood(m, "happy");
      }
    }, 1600);
  }),

  brief: walkStep(4),

  dueno: (step, el) => setMood($(".mascot", el), step >= 5 ? "joy" : "happy"),
};

/* ───────────── Back arc ───────────── */

// The loop closes from the last block back to the first, under the row
const drawBack = (alive) => {
  const blocks = $$(".blk", alive);
  const svg = $(".backarc", alive);
  const first = blocks[0];
  const last = blocks[blocks.length - 1];
  const top = Math.max(...blocks.map((b) => b.offsetTop + b.offsetHeight)) + 8;
  const from = last.offsetLeft + last.offsetWidth / 2;
  const to = first.offsetLeft + first.offsetWidth / 2;

  svg.setAttribute("width", alive.offsetWidth);
  svg.setAttribute("height", top + 60);
  $(".back", svg).setAttribute("d", `M${from} ${top} C${from} ${top + 46}, ${to} ${top + 46}, ${to} ${top + 4}`);
  $(".head", svg).setAttribute("d", `M${to - 9} ${top + 12} L${to} ${top} L${to + 9} ${top + 12}`);
};

/* ───────────── Chat ───────────── */

// One group per click: [kind, text, extra]. "me" and "cmd" lines are typed, the rest appear.
// "wait" lines spin for extra.ms and then settle on extra.done; extra.act runs a slide action
const CHATS = {
  preguntas: [
    [
      ["me", "Quiero que varias personas usen la lista. Preguntame las decisiones, de a una."],
      ["q", "¿Cada persona ve solo sus tareas, o hay listas compartidas?"],
      ["ans", "solo las suyas"],
